{"path":"about.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width,initial-scale=1" />
  <title>About — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#0e0f12;--card:#0f1316;--accent:#b9e3d9;--muted:#9aa7a1;--glass:rgba(255,255,255,0.04);--warm:#ffd9bf}
    html,body{height:100%;margin:0;font-family:Inter,ui-sans-serif,system-ui,-apple-system,"Segoe UI",Roboto,"Helvetica Neue",Arial;color:#e8f0ea;background:linear-gradient(180deg,#061216 0%, #07181a 60%);-webkit-font-smoothing:antialiased}
    header{display:flex;align-items:center;justify-content:space-between;padding:20px 28px;backdrop-filter:blur(6px)}
    .brand{display:flex;gap:12px;align-items:center}
    .logo{width:56px;height:56px;display:grid;place-items:center;border-radius:10px;background:linear-gradient(135deg,#0b2a2b,var(--card));box-shadow:0 6px 18px rgba(2,8,10,0.6);}
    .logo svg{width:36px;height:36px}
    nav a{color:#cfeee6;text-decoration:none;margin:0 10px;font-size:15px}
    main{max-width:980px;margin:28px auto;padding:28px;background:linear-gradient(180deg,rgba(255,255,255,0.02),transparent);border-radius:14px;box-shadow:0 12px 40px rgba(2,6,8,0.6)}
    .hero{display:grid;grid-template-columns:1fr 320px;gap:22px;align-items:center}
    h1{margin:0 0 8px 0;font-weight:700;color:#fff;letter-spacing:-0.4px}
    p.lead{color:var(--muted);margin:0 0 18px 0}
    .card{background:var(--card);padding:16px;border-radius:12px}
    .meta{font-size:13px;color:var(--muted)}
    .story{margin-top:18px;line-height:1.6;color:#dfeee6}
    footer{margin-top:22px;color:var(--muted);font-size:13px}
    .pattern{position:absolute;left:0;top:0;opacity:0.06;pointer-events:none}
    /* guided modal */
    .modal-backdrop{position:fixed;inset:0;background:linear-gradient(180deg,rgba(0,0,0,0.55),rgba(0,0,0,0.7));display:none;align-items:center;justify-content:center}
    .modal{background:linear-gradient(180deg,#071b1b,#081414);padding:20px;border-radius:14px;min-width:320px;max-width:680px;color:#e6fbf6}
    .breath-circle{width:180px;height:180px;border-radius:50%;background:radial-gradient(circle at 40% 30%,#9fe6d8 0,#6fc9b6 20%,transparent 60%);display:flex;align-items:center;justify-content:center;margin:12px auto;transition:all 600ms ease}
    .modal .controls{display:flex;gap:10px;justify-content:center;margin-top:12px}
    button.btn{background:var(--accent);border:none;padding:10px 14px;border-radius:10px;color:#04221f;font-weight:600;cursor:pointer}
    .small{font-size:13px;color:var(--muted)}
  </style>
</head>
<body>
  <svg class="pattern" width="600" height="600" viewBox="0 0 600 600" aria-hidden>
    <defs>
      <pattern id="dots-unique" x="0" y="0" width="60" height="60" patternUnits="userSpaceOnUse">
        <rect width="60" height="60" fill="transparent"></rect>
        <circle cx="10" cy="10" r="2" fill="#0b2e2c" />
        <circle cx="40" cy="40" r="2" fill="#083f3b" />
      </pattern>
      <linearGradient id="g1" x1="0" x2="1">
        <stop offset="0%" stop-color="#062e2f" stop-opacity="0.85" />
        <stop offset="100%" stop-color="#083a3a" stop-opacity="0.45" />
      </linearGradient>
    </defs>
    <rect width="600" height="600" fill="url(#g1)" />
    <rect width="600" height="600" fill="url(#dots-unique)" opacity="0.22"></rect>
  </svg>

  <header>
    <div class="brand">
      <div class="logo" aria-hidden>
        <svg viewBox="0 0 64 64" xmlns="http://www.w3.org/2000/svg">
          <rect x="6" y="10" width="52" height="44" rx="8" fill="#062929" />
          <g fill="#b9e3d9">
            <circle cx="20" cy="28" r="6" />
            <circle cx="36" cy="20" r="9" />
            <circle cx="46" cy="40" r="5" />
          </g>
        </svg>
      </div>
      <div>
        <div style="color:#fff;font-weight:700">{{BUSINESS_NAME}}</div>
        <div style="font-size:13px;color:var(--muted)">{{TAGLINE}}</div>
      </div>
    </div>
    <nav aria-label="Primary">
      <a href="index.html">Home</a>
      <a href="events.html">Gather</a>
      <a href="private-sessions.html">Solo Rituals</a>
      <a href="pricing.html">Costs</a>
      <a href="about.html">About the Circle</a>
      <a href="faq.html">FAQ</a>
      <a href="book.html" style="font-weight:700">Reserve</a>
      <a href="contact.html">Reach Out</a>
    </nav>
  </header>

  <main>
    <section class="hero">
      <div>
        <h1>We gather sound around simple beginnings</h1>
        <p class="lead">A compact explanation of how we shape a session: tuned layers, a small script of intention, and a few held rules that keep everyone safe and clear.</p>
        <div class="card">
          <div class="meta">What to expect</div>
          <p class="story">We open with a brief welcome, provide a short intention prompt, and offer 45–70 minutes of guided sound — bowls, chimes, and soft drones. Our focus is on supporting rest, reflection, and gentle re-patterning. If you arrive with expectations, we invite curiosity; if you arrive in need, we offer presence.</p>
          <div style="display:flex;gap:10px;margin-top:10px">
            <button class="btn" id="openTry">Try it now — 2 minutes</button>
            <a class="btn" href="book.html">Reserve a space</a>
          </div>
        </div>
        <div class="story">
          <h3>Our approach</h3>
          <p>We treat each event like a short ceremony: clear instructions, a small compass for intention, and sound arranged so each person can rest or attend. Facilitators are trained in listening, not in therapy; if you are working with medical or psychological needs, please consult your care provider before joining.</p>
        </div>
      </div>
      <aside class="card">
        <div style="font-weight:700;color:#e9fff8">Circle &amp; Sessions</div>
        <div class="meta" style="margin-top:6px">A few signature offerings</div>
        <ul style="padding-left:16px;margin-top:10px;color:#dceee7">
          <li><strong>Gathering</strong> — shared evening sessions (comfortable seating).</li>
          <li><strong>Grounding Private</strong> — 1:1 bespoke sessions for focused support.</li>
          <li><strong>Intro Series</strong> — three-session pathway to feel the form.</li>
        </ul>
        <div style="margin-top:12px;font-size:13px;color:var(--muted)">Phone: {{PHONE}} • <a href="mailto:{{EMAIL}}" style="color:var(--accent)">{{EMAIL}}</a></div>
      </aside>
    </section>

    <section style="margin-top:18px">
      <h3>Why these rooms matter</h3>
      <p class="story">We think of sound as a companion to attention: a way to hold stillness while feelings uncoil. The environment we architect is intentionally small — low lighting, guided pacing, and minimal talk. Our aim is to make it easy to arrive and to leave changed, if only by a degree.</p>
    </section>

    <section style="margin-top:18px" class="card">
      <h4 style="margin:0 0 8px 0">Accessibility &amp; care notes</h4>
      <p class="small">We welcome neurodiverse attendees and offer adaptations. However, some situations are contraindicated: if you have epilepsy (seizures triggered by sound or light), recent head/ear surgery, are in the first trimester of pregnancy without medical sign-off, or have implanted medical devices that might be affected by sustained vibrations, please consult your healthcare provider before attending. If you are managing severe anxiety, PTSD, or dissociation, consider joining with a support person or booking a private session to adapt pacing and proximity.</p>
    </section>

    <footer>
      <div>Questions? Call {{PHONE}} or write <a href="mailto:{{EMAIL}}">{{EMAIL}}</a>. To reserve, click Reserve or use the booking page.</div>
    </footer>
  </main>

  <div class="modal-backdrop" id="modal">
    <div class="modal" role="dialog" aria-modal="true" aria-labelledby="modalTitle">
      <h3 id="modalTitle">Try it now — a two-minute breath guide</h3>
      <div class="breath-circle" id="circle">Breathe</div>
      <div style="text-align:center;color:var(--muted)" id="cue">Tap start to begin. Follow the circle.</div>
      <div class="controls">
        <button class="btn" id="startBtn">Start</button>
        <button class="btn" id="stopBtn">Close</button>
      </div>
      <div style="margin-top:12px;text-align:center" class="small">A gentle paced inhale — hold — and longer exhale. No medical advice. If you feel faint, stop and sit down.</div>
    </div>
  </div>

  <script>
    // Guided breathing modal
    (function(){
      const modal = document.getElementById('modal');
      const open = document.getElementById('openTry');
      const startBtn = document.getElementById('startBtn');
      const stopBtn = document.getElementById('stopBtn');
      const circle = document.getElementById('circle');
      const cue = document.getElementById('cue');
      let timer=null; let phase=0; // 0 idle, 1 inhale,2 hold,3 exhale
      const phases = [ {name:'Inhale',dur:4000,scale:1.35}, {name:'Hold',dur:2000,scale:1.45}, {name:'Exhale',dur:6000,scale:0.6} ];

      open.addEventListener('click', ()=>{ modal.style.display='flex'; });
      stopBtn.addEventListener('click', ()=>{ close(); });

      function close(){ clearInterval(timer); timer=null; modal.style.display='none'; circle.style.transform='scale(1)'; cue.textContent='Tap start to begin. Follow the circle.' }

      startBtn.addEventListener('click', ()=>{
        if(timer){ clearInterval(timer); timer=null; startBtn.textContent='Start'; cue.textContent='Paused'; return; }
        startBtn.textContent='Pause'; phase=0; runCycle(); timer=setInterval(runCycle, phases[0].dur+phases[1].dur+phases[2].dur);
      });

      function runCycle(){
        // Inhale
        cue.textContent = phases[0].name;
        circle.style.transition='transform '+(phases[0].dur)+'ms ease-in-out, box-shadow 300ms';
        circle.style.transform='scale('+phases[0].scale+')';
        circle.style.boxShadow='0 0 40px rgba(175,245,227,0.15)';
        setTimeout(()=>{
          // Hold
          cue.textContent = phases[1].name;
          circle.style.transition='transform '+(phases[1].dur)+'ms linear';
          circle.style.transform='scale('+phases[1].scale+')';
          setTimeout(()=>{
            // Exhale
            cue.textContent = phases[2].name;
            circle.style.transition='transform '+(phases[2].dur)+'ms ease-in-out';
            circle.style.transform='scale('+phases[2].scale+')';
          }, phases[1].dur);
        }, phases[0].dur);
      }
    })();
  </script>
</body>
</html>"} 
{"path":"faq.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width,initial-scale=1" />
  <title>FAQ — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#071516;--card:#0d1413;--muted:#9fb7ad;--accent:#9fe6d8}
    body{margin:0;font-family:Inter,system-ui,Segoe UI,Roboto,Arial;color:#e6f7f0;background:var(--bg)}
    header{display:flex;align-items:center;justify-content:space-between;padding:18px 26px}
    .logo{display:flex;gap:12px;align-items:center}
    nav a{color:#cfeee6;text-decoration:none;margin:0 8px}
    main{max-width:920px;margin:22px auto;padding:20px}
    h1{margin:0 0 6px 0}
    .grid{display:grid;grid-template-columns:2fr 1fr;gap:18px}
    .card{background:linear-gradient(180deg,rgba(255,255,255,0.02),transparent);padding:16px;border-radius:12px}
    details{background:var(--card);padding:12px;border-radius:10px;margin-bottom:10px}
    summary{font-weight:700;cursor:pointer}
    .muted{color:var(--muted);font-size:13px}
    .cta{display:block;margin-top:12px}
    .modal-backdrop{position:fixed;inset:0;background:rgba(2,6,6,0.6);display:none;align-items:center;justify-content:center}
    .modal{background:#071515;padding:18px;border-radius:12px;color:#e6fbf6;max-width:640px}
    textarea{width:100%;height:120px;border-radius:8px;padding:8px;border:none;background:#081313;color:#e8fff7}
    button.btn{background:var(--accent);border:none;padding:10px 12px;border-radius:8px;color:#04342f;font-weight:700;cursor:pointer}
  </style>
</head>
<body>
  <header>
    <div class="logo">
      <div style="width:44px;height:44px;background:#082e2d;border-radius:8px"></div>
      <div>
        <div style="color:#fff;font-weight:700">{{BUSINESS_NAME}}</div>
        <div style="font-size:13px;color:var(--muted)">Questions answered</div>
      </div>
    </div>
    <nav>
      <a href="index.html">Home</a>
      <a href="events.html">Gather</a>
      <a href="private-sessions.html">Solo Rituals</a>
      <a href="about.html">About</a>
      <a href="book.html">Reserve</a>
      <a href="contact.html">Reach Out</a>
    </nav>
  </header>

  <main>
    <h1>Common questions</h1>
    <p class="muted">If you don’t find what you need here, email <a href="mailto:{{EMAIL}}">{{EMAIL}}</a> or call {{PHONE}}.</p>

    <div class="grid">
      <section>
        <div class="card">
          <details open>
            <summary>What should I bring?</summary>
            <div class="muted" style="margin-top:8px">Most people bring a mat or cushion, a light blanket, and anything making them comfortable (eye mask, small bolster). We recommend layers — spaces can be cool.</div>
          </details>
          <details>
            <summary>How loud is it?</summary>
            <div class="muted" style="margin-top:8px">Sound is intentionally gentle but can include low frequencies. We avoid sudden loud bangs. If you are sensitive to vibration, choose a seat near the door or request a softer mix by email.</div>
          </details>
          <details>
            <summary>Are sessions therapeutic?</summary>
            <div class="muted" style="margin-top:8px">Sessions are not therapy. Facilitators are not therapists unless explicitly stated. If you are in active mental health treatment, check with your provider to confirm soundwork is appropriate for you.</div>
          </details>

          <details>
            <summary>Cancellation &amp; refunds</summary>
            <div class="muted" style="margin-top:8px">Refunds are available up to 48 hours before the event. Within 48 hours we may offer credit for a future session depending on circumstance.</div>
          </details>

          <details>
            <summary>Contraindications and safety</summary>
            <div class="muted" style="margin-top:8px">Please do not attend if you have medical devices that can be affected by sustained vibrations without medical clearance. If you have epilepsy, recent cranial surgery, or are pregnant, consult your care provider first. If you experience intense dissociation, consider attending with a companion or choosing a private session so we can adapt the environment.</div>
          </details>
        </div>
      </section>

      <aside>
        <div class="card">
          <h3 style="margin-top:0">Quick helps</h3>
          <p class="muted">Short practices available right here in the page. Try a 3-minute intention set to feel what a brief pause can do. No audio required — text prompts guide you.</p>
          <div style="display:flex;gap:8px;margin-top:10px">
            <button class="btn" id="openJournal">Try it now — intention</button>
            <a class="btn" href="book.html">Plan a visit</a>
          </div>
          <p class="muted" style="margin-top:12px">Phone: {{PHONE}}</p>
        </div>
      </aside>
    </div>

    <section style="margin-top:18px" class="card">
      <h4 style="margin:0 0 8px 0">Still curious?</h4>
      <p class="muted">We keep event sizes small and seats limited. If you need to adapt seating or have noise sensitivity, write to <a href="mailto:{{EMAIL}}">{{EMAIL}}</a> before your visit so we can prepare.</p>
    </section>
  </main>

  <div class="modal-backdrop" id="jModal">
    <div class="modal" role="dialog" aria-modal="true">
      <h3>Try a brief intention &amp; journaling</h3>
      <p class="muted">Set a simple focus for the next few minutes. Answer the prompts below and close when you are finished.</p>
      <div style="margin-top:8px">
        <label class="muted">Choose a focus:</label>
        <div style="display:flex;gap:8px;margin-top:8px">
          <button class="btn" data-focus="rest">Rest</button>
          <button class="btn" data-focus="clarity">Clarity</button>
          <button class="btn" data-focus="gratitude">Gratitude</button>
        </div>
      </div>
      <div style="margin-top:12px">
        <label class="muted">Write one line:</label>
        <textarea id="journalArea" placeholder="I am here to ..."></textarea>
      </div>
      <div style="display:flex;gap:8px;justify-content:flex-end;margin-top:10px">
        <button class="btn" id="saveNote">Save locally</button>
        <button class="btn" id="closeJournal">Close</button>
      </div>
      <div id="savedMessage" class="muted" style="margin-top:10px;display:none">Saved to this browser for your session.</div>
    </div>
  </div>

  <script>
    // Intentional journaling modal
    (function(){
      const open = document.getElementById('openJournal');
      const modal = document.getElementById('jModal');
      const closeBtn = document.getElementById('closeJournal');
      const saveBtn = document.getElementById('saveNote');
      const area = document.getElementById('journalArea');
      const saved = document.getElementById('savedMessage');

      open.addEventListener('click', ()=>{ modal.style.display='flex'; });
      closeBtn.addEventListener('click', ()=>{ modal.style.display='none'; saved.style.display='none'; });
      saveBtn.addEventListener('click', ()=>{
        const note = area.value || '';
        try{ localStorage.setItem('sb_intention', note); saved.style.display='block'; saved.textContent='Saved to this browser for your session.' }catch(e){ saved.style.display='block'; saved.textContent='Could not save locally.' }
      });

      // quick focus buttons
      document.querySelectorAll('[data-focus]').forEach(btn=>{
        btn.addEventListener('click', ()=>{ area.value = ({rest:'I will notice my breath for two minutes.',clarity:'I will pay attention to one thought and release judgments.',gratitude:'I will name three small things I notice that I am thankful for.'})[btn.dataset.focus]; });
      });
    })();
  </script>
</body>
</html>"} 
{"path":"book.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width,initial-scale=1" />
  <title>Reserve — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#071617;--card:#0b1312;--accent:#8ce1cc;--muted:#9dbdb2}
    body{margin:0;font-family:Inter,system-ui,Segoe UI,Roboto,Arial;color:#e8fdf6;background:var(--bg)}
    header{display:flex;align-items:center;justify-content:space-between;padding:16px 22px}
    nav a{color:#cfeee6;margin:0 8px;text-decoration:none}
    main{max-width:980px;margin:20px auto;padding:20px}
    .columns{display:grid;grid-template-columns:1fr 360px;gap:18px}
    .card{background:linear-gradient(180deg,rgba(255,255,255,0.02),transparent);padding:14px;border-radius:12px}
    label{display:block;font-weight:700;margin-bottom:6px}
    select,input[type=date]{width:100%;padding:8px;border-radius:8px;border:none;background:#071312;color:#e8fff7}
    .seats{display:flex;gap:8px;flex-wrap:wrap;margin-top:8px}
    .seat{width:44px;height:44px;border-radius:8px;display:grid;place-items:center;background:#092524;color:#7fd6c4;cursor:pointer}
    .seat.taken{background:#1b2a2a;color:#3b5954;cursor:not-allowed;opacity:0.6}
    .seat.selected{background:var(--accent);color:#052f2a}
    .packing{margin-top:12px}
    button.btn{background:var(--accent);border:none;padding:10px 12px;border-radius:8px;color:#042f2a;font-weight:700;cursor:pointer}
    .price{font-size:18px;font-weight:800;color:#dff6ef;margin-top:8px}
    .small{font-size:13px;color:var(--muted)}
  </style>
</head>
<body>
  <header>
    <div style="display:flex;gap:12px;align-items:center">
      <div style="width:44px;height:44px;background:#082e2d;border-radius:8px"></div>
      <div>
        <div style="color:#fff;font-weight:700">{{BUSINESS_NAME}}</div>
        <div style="font-size:12px;color:var(--muted)">Reserve a spot</div>
      </div>
    </div>
    <nav>
      <a href="index.html">Home</a>
      <a href="events.html">Gather</a>
      <a href="pricing.html">Costs</a>
      <a href="about.html">About</a>
      <a href="contact.html">Reach Out</a>
    </nav>
  </header>

  <main>
    <div class="columns">
      <section>
        <div class="card">
          <h2 style="margin-top:0">Reserve your seat</h2>
          <p class="small">Select a date, pick your seat, and build a quick packing list tailored to how you plan to use the session.</p>

          <form id="bookForm" onsubmit="return false;">
            <div style="margin-top:12px">
              <label for="date">Choose a date</label>
              <select id="date"></select>
            </div>

            <div style="margin-top:12px">
              <label>Select seat(s)</label>
              <div class="seats" id="seats"></div>
              <div class="small" id="seatNotice">Select 1–4 seats. Availability is simulated locally.</div>
            </div>

            <div style="margin-top:12px">
              <label for="intent">Primary intention</label>
              <select id="intent">
                <option value="rest">Rest &amp; un-tension</option>
                <option value="focus">Release to focus</option>
                <option value="reflect">Private reflection</option>
                <option value="sleep">Pre-sleep unwind</option>
              </select>
            </div>

            <div class="packing" id="packing">
              <h4 style="margin:10px 0 6px 0">Packing list — suggested</h4>
              <ul id="packingList" style="padding-left:18px;color:#dff7f0"></ul>
            </div>

            <div style="margin-top:12px;display:flex;align-items:center;justify-content:space-between">
              <div>
                <div class="price" id="total">Total: $0</div>
                <div class="small">Price per seat is shown below.</div>
              </div>
              <div>
                <button class="btn" id="proceed">{{PRIMARY_CTA_LABEL}}</button>
              </div>
            </div>

            <div style="margin-top:10px" class="small">By reserving you agree to our safety guidelines. Contraindications: please consult your provider if pregnant, recently post-operative, have epilepsy, implanted devices, or conditions affected by vibration. See FAQ for more.</div>

          </form>
        </div>

        <div class="card" style="margin-top:12px">
          <h4 style="margin:0 0 8px 0">Simulated calendar</h4>
          <div id="eventsList" class="small"></div>
        </div>
      </section>

      <aside>
        <div class="card">
          <h4 style="margin-top:0">Quick details</h4>
          <p class="small">Sessions run 60 minutes. Suggested price tiers below are framed as "Circle" access. Private sessions are listed on the private page.</p>
          <ul style="padding-left:18px;color:#dff7f0">
            <li>Circle Access — $28 / seat</li>
            <li>Reserved Comfort (front rows) — +$6 / seat</li>
            <li>Private — see private-sessions.html</li>
          </ul>
          <div style="margin-top:12px;font-size:13px;color:var(--muted)">Questions? <a href="mailto:{{EMAIL}}">{{EMAIL}}</a> • {{PHONE}}</div>
        </div>
      </aside>
    </div>
  </main>

  <script>
    // Booking seat selector + packing list generator (local only)
    (function(){
      const seatContainer = document.getElementById('seats');
      const dateSelect = document.getElementById('date');
      const packingList = document.getElementById('packingList');
      const intent = document.getElementById('intent');
      const totalEl = document.getElementById('total');
      const proceed = document.getElementById('proceed');
      const eventsList = document.getElementById('eventsList');

      // seed pseudo-random for deterministic behavior across loads
      function mulberry32(a) { return function() { var t = a += 0x6D2B79F5; t = Math.imul(t ^ t >>> 15, t | 1); t ^= t + Math.imul(t ^ t >>> 7, t | 61); return ((t ^ t >>> 14) >>> 0) / 4294967296; }}
      const rng = mulberry32(2960292377 ^ 0x9e3779b9);

      // create simulated dates
      const dates = [];
      for(let i=1;i<=6;i++){ const d=new Date(); d.setDate(d.getDate()+i*3); dates.push(d); }
      dates.forEach(d=>{ const opt=document.createElement('option'); opt.value=d.toISOString().slice(0,10); opt.textContent=d.toDateString(); dateSelect.appendChild(opt); });

      // simulate seat map (12 seats)
      function renderSeats(){ seatContainer.innerHTML='';
        const takenMask = Math.floor(rng()*0xFFF);
        for(let i=1;i<=12;i++){
          const btn=document.createElement('div'); btn.className='seat'; btn.textContent=i;
          const taken = (takenMask >> i) & 1; if(taken){ btn.classList.add('taken'); }
          btn.dataset.id=i; seatContainer.appendChild(btn);
        }
      }
      renderSeats();

      // pick seats
      seatContainer.addEventListener('click', e=>{
        const el = e.target.closest('.seat'); if(!el || el.classList.contains('taken')) return;
        el.classList.toggle('selected'); computeTotal(); updatePacking();
      });

      function computeTotal(){
        const base = 28; const comfortAdd = 6; // pricing model
        const selected = seatContainer.querySelectorAll('.seat.selected').length;
        let total = selected * base;
        // small heuristic: seats 1-3 are 'front' and cost more
        seatContainer.querySelectorAll('.seat.selected').forEach(s=>{ const id=Number(s.dataset.id); if(id<=3) total += comfortAdd; });
        totalEl.textContent = 'Total: $' + (total);
      }

      // Packing list generator based on intention + seat choices
      function updatePacking(){
        packingList.innerHTML='';
        const focus = intent.value;
        const selected = seatContainer.querySelectorAll('.seat.selected').length;
        const items = new Set();
        // base items
        items.add('Mat or yoga mat'); items.add('Blanket');
        // adapt to intention
        if(focus==='rest'){ items.add('Small pillow or neck roll'); items.add('Eye mask'); }
        if(focus==='focus'){ items.add('Notebook & pen'); items.add('Water bottle'); }
        if(focus==='reflect'){ items.add('Journal & pen'); items.add('Light sweater'); }
        if(focus==='sleep'){ items.add('Cozy socks'); items.add('Lavender sachet (optional)'); }
        // if multiple seats (bringing a friend), suggest extras
        if(selected>1){ items.add('Shared blanket or extra cushion'); }
        // if front seats selected, note ear sensitivity
        Array.from(seatContainer.querySelectorAll('.seat.selected')).forEach(s=>{ if(Number(s.dataset.id)<=3) items.add('Ear-friendly earplugs (recommended for front seating)'); });

        // render
        items.forEach(it=>{ const li=document.createElement('li'); li.textContent=it; packingList.appendChild(li); });
      }

      // initial compute
      computeTotal(); updatePacking();

      // when intent changes
      intent.addEventListener('change', updatePacking);

      // populate a small events list (next-event module)
      (function renderEvents(){
        const next = dates.slice(0,4).map((d,i)=>({date:d, label:['Evening Circle','Midweek Gathering','Late Calm','Weekend Circle'][i%4], spots:Math.floor(rng()*12)}));
        eventsList.innerHTML = next.map(e=>`<div style="margin-bottom:8px">${e.date.toDateString()} — <strong style="color:#dff7f0">${e.label}</strong> • spots (approx): ${12-e.spots}</div>`).join('');
      })();

      // proceed -> build a local confirmation and direct to PRIMARY_CTA_URL
      proceed.addEventListener('click', ()=>{
        const seats = Array.from(seatContainer.querySelectorAll('.seat.selected')).map(n=>n.dataset.id);
        if(seats.length===0){ alert('Please select at least one seat.'); return; }
        const summary = {date:dateSelect.value,seats:seats,intent:intent.value,total:totalEl.textContent};
        // store locally and then redirect to placeholder URL
        try{ localStorage.setItem('sb_reservation', JSON.stringify(summary)); }catch(e){ /* ignore */ }
        // redirect to primary CTA URL placeholder
        window.location.href = '{{PRIMARY_CTA_URL}}';
      });

    })();
  </script>
</body>
